-- every statement picks its own W or R
CONSISTENCY ONE;      -- W = 1: fast, works with 2 of 3 replicas down
UPDATE payments.balances SET balance_minor = 7000 WHERE account_id = 'A-1001';

CONSISTENCY QUORUM;   -- R = 2: overlaps any QUORUM write (2 + 2 > 3)
SELECT balance_minor FROM payments.balances WHERE account_id = 'A-1001';

