// every write goes to the partition's leader, which answers once
// a quorum of the partition's replicas has logged it
ddb.putItem { it.tableName("payments").item(profile) }

// a read picks: any replica, half price, may be behind ...
ddb.getItem { it.tableName("payments").key(key) }
// ... or the leader, which has every acknowledged write
ddb.getItem { it.tableName("payments").key(key).consistentRead(true) }

